function step(t){return Promise.resolve(2*t)}function chainStyle(){const t=[];return step(1).then(function(n){return t.push("a="+n),step(n)}).then(function(n){if(t.push("b="+n),n>100)throw new Error("too big");return step(n)}).then(function(n){return t.push("c="+n),t}).catch(function(n){return t.push("caught:"+n.message),t})}async function asyncStyle(){const t=[];try{const n=await step(1);t.push("a="+n);const e=await step(n);if(t.push("b="+e),e>100)throw new Error("too big");const s=await step(e);t.push("c="+s)}catch(n){t.push("caught:"+n.message)}return t}chainStyle().then(function(t){print("chain:",t.join(","))}),asyncStyle().then(function(t){print("async:",t.join(","))});